def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my = [h[0] for h in history]
    op = [h[1] for h in history]
    opD = op.count('D')
    myD = my.count('D')
    opC = n - opD
    remaining = 100 - n

    # Near endgame: exploit if opponent is unlikely to punish meaningfully.
    if remaining <= 2:
        return 'D'
    if remaining <= 4:
        recent_op = op[-6:] if n >= 6 else op
        if recent_op.count('D') >= 2:
            return 'D'
        return 'C'

    # Perfect cooperator so far: keep cooperating, small probe late.
    if opD == 0:
        if n >= 60 and n % 12 == 11:
            return 'D'
        return 'C'

    # Heavy defector: punish, but occasionally probe for reset.
    if opD * 3 > n * 2:
        if n % 11 == 0:
            return 'C'
        return 'D'

    # Very cooperative overall: cooperate, rare exploitation.
    if opD * 6 < n:
        if n >= 25 and n % 17 == 16:
            return 'D'
        return 'C'

    # Alternating defection spirals: break out occasionally.
    if n >= 4 and op[-1] == 'D' and op[-2] == 'D' and my[-1] == 'D' and my[-2] == 'D':
        if n % 5 == 0:
            return 'C'

    last_op = op[-1]

    # Direct retaliation for a fresh defection.
    if last_op == 'D':
        rec = op[-7:] if n >= 7 else op
        recD = rec.count('D')
        if recD >= 3:
            return 'D'
        if recD == 2 and n >= 3:
            # moderate retaliation, forgive once in a while
            if rng.random() < 0.2:
                return 'C'
            return 'D'
        # single defection: retaliate with high probability
        if rng.random() < 0.75:
            return 'D'
        return 'C'

    # Last opponent was C. Reward cooperation; check for signal of exploitation.
    if n >= 5:
        rec = op[-5:]
        recD = rec.count('D')
        if recD == 0:
            # sustained cooperation
            if n >= 40 and n % 25 == 24 and opD > 0:
                return 'D'
            return 'C'
        if recD == 1:
            return 'C'
        if recD >= 3:
            return 'D'
        if recD == 2:
            # mixed signals; lean toward cooperation but stay wary
            if rng.random() < 0.3:
                return 'D'
            return 'C'

    # Short history: friendly tit-for-tat.
    if last_op == 'C':
        return 'C'
    return 'D'
